// Linker View: Symbol Resolution & Relocation for C Symbols

// 1. Symbol Table Entry (Resolution Focus)
struct Symbol {
    char* name;
    enum { DEF, UNDEF, WEAK } binding;
    uint32_t section_idx; // 0 for UNDEF
    uint32_t rel_addr;    // Relative offset in section
};

// 2. Relocation Table Entry (Relocation Focus)
struct Rela {
    uint32_t offset;    // Offset in section needing fixup
    uint32_t symbol_idx;
    enum { R_X86_64_PC32 } type; // Type of fixup needed
};

// 3. Linker Action: Calculate Target Address
uint32_t Resolved_Addr =
    Symbol[idx].abs_base + Symbol[idx].rel_addr;

// 4. Applying Relocation (e.g., PC32)
uint32_t P_Address = Section_Base + Rela.offset;

Fixup_Value = Resolved_Addr - P_Address;
*((uint32_t*)P_Address) += Fixup_Value;
// The memory location at P_Address is updated.
